import { FileText, Scale, Search, ShieldCheck } from "lucide-react";

import {
    Card,
    CardContent,
    CardDescription,
    CardFooter,
    CardHeader,
    CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";

export default function WorkflowsPage() {
    const workflows = [
        {
            title: "Contract Analysis",
            description: "Automated risk assessment and clause review for legal contracts.",
            icon: FileText,
            details: "Upload contracts to identify potential risks, non-standard clauses, and get mitigation suggestions based on your playbook.",
        },
        {
            title: "Compliance Scanner",
            description: "Check documents against GDPR, HIPAA, and regional regulations.",
            icon: ShieldCheck,
            details: "Scan your documentation repository to ensure all files meet the latest compliance standards and flag violations.",
        },
        {
            title: "Legal Research Assistant",
            description: "Find relevant case law and precedents faster.",
            icon: Scale,
            details: "An agent that searches through case law databases to find relevant precedents, summarising key findings and citations.",
        },
        {
            title: "IP Discovery",
            description: "Patent overlap and intellectual property uniqueness search.",
            icon: Search,
            details: "Analyze patent databases to check for overlapping intellectual property and generate comprehensive uniqueness reports.",
        },
    ];

    return (
        <div className="flex flex-1 flex-col h-full overflow-hidden">
            <div className="flex-1 overflow-y-auto p-6 no-scrollbar">
                <div className="flex flex-col gap-2 mb-6">
                    <h1 className="text-2xl font-bold tracking-tight">Agent Workflows</h1>
                    <p className="text-muted-foreground">
                        Select an agentic workflow to automate your legal and document processes.
                    </p>
                </div>

                <div className="grid gap-8 md:grid-cols-2 lg:grid-cols-2">
                    {workflows.map((workflow) => (
                        <Card key={workflow.title} className="flex flex-col justify-between hover:shadow-lg transition-all border-2">
                            <CardHeader>
                                <div className="flex items-center gap-3 mb-2">
                                    <div className="p-2 bg-primary/10 rounded-lg text-primary">
                                        <workflow.icon className="h-6 w-6" />
                                    </div>
                                    <CardTitle className="text-xl">{workflow.title}</CardTitle>
                                </div>
                                <CardDescription>{workflow.description}</CardDescription>
                            </CardHeader>
                            <CardContent>
                                <p className="text-sm text-foreground/80">
                                    {workflow.details}
                                </p>
                            </CardContent>
                            <CardFooter>
                                <Button className="w-full">Start Workflow</Button>
                            </CardFooter>
                        </Card>
                    ))}
                </div>
            </div>
        </div>
    );
}
